css:
.sl-footer-modern {
    padding-top: 5rem;
    font-family: var(--smartlearn-body-font, inherit);
}
.sl-footer-modern .sl-footer-cta-row { margin-bottom: 4rem; }
.sl-footer-modern .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-footer-modern .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-footer-modern.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-footer-modern .sl-bg-card {
    background-color: var(--smartlearn-card-bg) !important;
}
.sl-footer-modern.sl-border,
.sl-footer-modern .row.sl-border,
.sl-footer-modern .sl-social-btn.sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-footer-modern .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg) !important;
    border-color: var(--smartlearn-btn-bg) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
}
.sl-footer-modern .sl-btn-primary:hover,
.sl-footer-modern .sl-btn-primary:focus-visible,
.sl-footer-modern .sl-btn-primary:active {
    background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important;
    border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    box-shadow: 0 4px 12px color-mix(in srgb, var(--smartlearn-primary) 30%, transparent) !important;
}
.sl-footer-modern .sl-cta-arrow::after {
    content: "→";
    display: inline-block;
    transition: transform 0.2s ease;
}
[dir="rtl"] .sl-footer-modern .sl-cta-arrow::after {
    transform: scaleX(-1);
}
.sl-footer-modern .sl-cta-arrow:hover::after {
    transform: translateX(4px);
}
[dir="rtl"] .sl-footer-modern .sl-cta-arrow:hover::after {
    transform: scaleX(-1) translateX(4px);
}
@keyframes sl-footer-modern-glow {
    0%, 100% { opacity: 0.75; }
    50% { opacity: 1; }
}
.sl-footer-modern .sl-bg-glow {
    z-index: 0;
    pointer-events: none;
    background: radial-gradient(ellipse at top, color-mix(in srgb, var(--smartlearn-primary) 10%, transparent) 0%, transparent 70%);
    animation: sl-footer-modern-glow 8s ease-in-out infinite;
}
.sl-footer-modern .sl-tracking-wide { letter-spacing: 0.05em; font-size: 0.85rem; }
.sl-footer-modern .sl-footer-link { transition: color 0.2s ease; }
.sl-footer-modern .sl-footer-link:hover,
.sl-footer-modern .sl-footer-link:focus-visible {
    color: var(--smartlearn-primary) !important;
    text-decoration: underline !important;
}
.sl-footer-modern .sl-social-btn {
    width: 44px; height: 44px;
    transition: transform 0.25s ease, background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}
.sl-footer-modern .sl-social-btn:hover,
.sl-footer-modern .sl-social-btn:focus-visible {
    transform: translateY(-4px);
    background-color: var(--smartlearn-btn-bg) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    border-color: var(--smartlearn-btn-bg) !important;
    box-shadow: 0 8px 15px color-mix(in srgb, var(--smartlearn-primary) 25%, transparent) !important;
}
.sl-footer-modern .sl-hover-lift { transition: transform 0.2s ease, box-shadow 0.2s ease; }
.sl-footer-modern .sl-hover-lift:hover { transform: translateY(-3px); }
.sl-footer-modern a:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-footer-modern .sl-bg-glow { animation: none; }
    .sl-footer-modern .sl-cta-arrow::after,
    .sl-footer-modern .sl-footer-link,
    .sl-footer-modern .sl-social-btn,
    .sl-footer-modern .sl-hover-lift { transition: none; }
    .sl-footer-modern .sl-social-btn:hover,
    .sl-footer-modern .sl-social-btn:focus-visible,
    .sl-footer-modern .sl-hover-lift:hover { transform: none; }
}
